/* Língua Portuguesa — 10 itens inéditos por subtópico do Edital PRF nº 1/2021 (5 C + 5 E cada). Parte B: tópicos 5.6 a 7.4. */
(function () {
  var D = 'Língua Portuguesa', n = 100;
  function q(topico, tema, gabarito, enunciado, comentario) {
    n++;
    return { id: 'LP-' + String(n).padStart(3, '0'), disciplina: D, tema: tema, topico: topico,
             gabarito: gabarito, enunciado: enunciado, comentario: comentario };
  }
  var T56 = '5.6 Regência verbal e nominal', M56 = 'Concordância e regência';
  var T57 = '5.7 Crase', M57 = 'Crase';
  var T58 = '5.8 Colocação pronominal', M58 = 'Colocação pronominal';
  var T61 = '6.1 Significação das palavras', T62 = '6.2 Substituição de palavras ou trechos',
      T63 = '6.3 Reorganização de orações e períodos', T64 = '6.4 Reescrita em diferentes gêneros e níveis de formalidade', M6 = 'Reescrita';
  var T71 = '7.1 Aspectos gerais da redação oficial', T72 = '7.2 Finalidade dos expedientes oficiais',
      T73 = '7.3 Adequação da linguagem ao documento', T74 = '7.4 Adequação do formato ao gênero', M7 = 'Redação oficial';

  window.QUESTOES = (window.QUESTOES || []).concat([
    /* ===== 5.6 Regência verbal e nominal ===== */
    q(T56, M56, 'C', 'No trecho “Os motoristas devem obedecer à sinalização da rodovia.”, a regência do verbo “obedecer” está de acordo com a norma-padrão.',
      'Correto. Regência verbal é a relação entre o verbo e seu complemento: o verbo exige ou não preposição?\n"Obedecer" (e seu antônimo "desobedecer") é TRANSITIVO INDIRETO: quem obedece, obedece A algo ou A alguém.\nNo trecho: obedecer + a (preposição) + a (artigo de "a sinalização") = obedecer À sinalização. A crase confirma a regência correta.\nOutros exemplos: "obedecer ao CTB", "obedecer aos superiores", "desobedecer à ordem".\nObservação: mesmo sendo transitivo indireto, "obedecer" admite voz passiva ("A sinalização foi obedecida"). É uma exceção clássica.'),
    q(T56, M56, 'E', 'No trecho “O agente assistiu o acidente da margem da pista.”, a regência do verbo “assistir”, no sentido de presenciar, está de acordo com a norma-padrão.',
      'Errado. O verbo "assistir" muda de regência conforme o sentido. É um dos mais cobrados em prova:\n• Assistir = VER, PRESENCIAR → transitivo INDIRETO (preposição "a"): "assistiu AO acidente", "assistir AO jogo", "assistir À palestra".\n• Assistir = AJUDAR, PRESTAR ASSISTÊNCIA → transitivo DIRETO: "O socorrista assistiu O ferido".\n• Assistir = CABER, SER DE DIREITO → transitivo indireto: "Esse direito assiste AO cidadão".\n• Assistir = MORAR (uso antigo) → intransitivo, com preposição "em".\nNo trecho, o sentido é presenciar. Logo, o correto é "assistiu AO acidente".'),
    q(T56, M56, 'C', 'No trecho “Prefiro fiscalizar a rodovia a ficar no escritório.”, a regência do verbo “preferir” está de acordo com a norma-padrão.',
      'Correto. Pela norma-padrão, o verbo "preferir" segue a estrutura: preferir ALGO A ALGO (com a preposição "a").\n"Prefiro fiscalizar a rodovia A ficar no escritório."\nConstruções INADEQUADAS (comuns na fala):\n• "Prefiro fiscalizar DO QUE ficar no escritório."\n• "Prefiro MAIS fiscalizar..."\n• "Prefiro MIL VEZES fiscalizar..."\nExplicação: o próprio verbo já carrega a ideia de "querer mais", de modo que "mais" e "do que" seriam redundantes.'),
    q(T56, M56, 'E', 'No trecho “O condutor esqueceu dos documentos no posto.”, a regência do verbo “esquecer” está de acordo com a norma-padrão.',
      'Errado. Os verbos "esquecer" e "lembrar" têm duas construções corretas, e o erro está em misturá-las:\n• SEM pronome → transitivo DIRETO (sem preposição): "O condutor esqueceu OS documentos."\n• COM pronome → transitivo INDIRETO (com preposição "de"): "O condutor esqueceu-SE DOS documentos."\nO trecho "esqueceu DOS documentos" usa a preposição sem o pronome, uma mistura inadequada.\nA mesma regra vale para "lembrar": "lembrei o nome" / "lembrei-me do nome" (e não "lembrei do nome", segundo a norma tradicional).'),
    q(T56, M56, 'C', 'No trecho “Muitos servidores aspiram ao cargo de chefia do posto.”, a regência do verbo “aspirar”, no sentido de desejar, está de acordo com a norma-padrão.',
      'Correto. "Aspirar" também muda de regência conforme o sentido:\n• Aspirar = DESEJAR, ALMEJAR, PRETENDER → transitivo INDIRETO (preposição "a"): "aspiram AO cargo", "aspirava À aprovação".\n• Aspirar = INALAR, SORVER, RESPIRAR → transitivo DIRETO: "aspirou O ar puro", "aspirou a fumaça".\nNo trecho, o sentido é desejar o cargo de chefia. Logo, "aspiram AO cargo" está correto.\nObservação: no sentido de desejar, não se usa "lhe"; usa-se "a ele/a ela": "Aspiram a ele" (e não "aspiram-lhe").'),
    q(T56, M56, 'E', 'No trecho “Chegamos no posto às seis horas da manhã.”, a regência do verbo “chegar” está de acordo com a norma-padrão.',
      'Errado. Verbos de MOVIMENTO como "chegar", "ir", "voltar", "levar" e "dirigir-se" exigem a preposição "A" para indicar o destino, e não "em".\nCorreto: "Chegamos AO posto às seis horas da manhã."\nOutros exemplos: "Cheguei A Brasília"; "Fomos À delegacia"; "Voltaram AO local do acidente".\n"Chegar em" é extremamente comum na fala ("cheguei em casa"), mas a norma-padrão prescreve "chegar a".\nDica: essa regra explica a crase em "Fomos à delegacia" (ir a + a delegacia).'),
    q(T56, M56, 'C', 'No trecho “A medida adotada pelo órgão é compatível com a legislação de trânsito.”, a regência do adjetivo “compatível” está de acordo com a norma-padrão.',
      'Correto. Este é um caso de REGÊNCIA NOMINAL: a relação entre um nome (substantivo, adjetivo, advérbio) e seu complemento.\nO adjetivo "compatível" rege a preposição "COM": compatível COM algo.\nOutros nomes que pedem "com": incompatível com, compatível com, contente com, cuidadoso com, solidário com.\nExemplos de outras regências nominais frequentes: acessível A, apto A/PARA, favorável A, contrário A, obediência A, preferível A, residente EM, situado EM, ávido DE/POR.'),
    q(T56, M56, 'E', 'No trecho “O policial informou o motorista da infração cometida.”, há erro de regência, pois o verbo “informar” admite exclusivamente a construção com objeto direto de coisa e objeto indireto de pessoa.',
      'Errado. O verbo "informar" é transitivo direto e indireto e admite DUAS construções corretas:\n1) Informar ALGUÉM DE/SOBRE algo: "O policial informou O MOTORISTA DA infração." (objeto direto = pessoa; objeto indireto = coisa). É o caso do trecho.\n2) Informar ALGO A alguém: "O policial informou A INFRAÇÃO AO MOTORISTA." (objeto direto = coisa; objeto indireto = pessoa).\nO item erra ao dizer que só a segunda é admitida.\nAtenção: não se pode ter dois objetos diretos ou dois indiretos ao mesmo tempo. Verbos com o mesmo comportamento: avisar, certificar, cientificar, notificar, prevenir.'),
    q(T56, M56, 'C', 'No trecho “A imprudência implica risco para todos os usuários da via.”, a ausência de preposição após “implica” está de acordo com a norma-padrão tradicional, já que, no sentido de acarretar, o verbo é transitivo direto.',
      'Correto. Segundo a gramática normativa tradicional, "implicar" no sentido de ACARRETAR, TER COMO CONSEQUÊNCIA é transitivo DIRETO, sem preposição.\nCorreto: "A imprudência implica risco." / "O atraso implica multa."\nInadequado (pela tradição): "implica EM risco".\nAtenção: a construção "implicar em" é muito usada e alguns dicionários já a registram, mas, em prova, siga a regra tradicional, até porque o item menciona a "norma-padrão tradicional".\nOutros sentidos: "implicar com alguém" (= antipatizar, provocar) é transitivo indireto, com "com"; "implicar-se em algo" (= envolver-se) também é correto.'),
    q(T56, M56, 'E', 'No trecho “A rodovia que nos referimos está interditada.”, a regência está de acordo com a norma-padrão.',
      'Errado. Quando o verbo da oração adjetiva exige preposição, essa preposição deve vir ANTES do pronome relativo.\n"Referir-se" exige a preposição "a": quem se refere, refere-se A algo.\nOrdem direta: "Nós nos referimos À rodovia."\nCom o relativo: "A rodovia A QUE nos referimos" ou "A rodovia À QUAL nos referimos".\nOmitir a preposição antes do relativo é chamado de "queísmo" ou "relativa cortadora". É comum na fala, mas inadequado à norma-padrão.\nOutros exemplos: "o cargo a que aspiro", "o filme a que assisti", "a pessoa de quem gosto", "o fato de que me lembro".'),

    /* ===== 5.7 Crase ===== */
    q(T57, M57, 'C', 'No trecho “O agente entregou a notificação à motorista.”, o emprego do acento indicativo de crase está correto.',
      'Correto. A crase é a fusão da preposição "a" com o artigo definido feminino "a" (a + a = à).\nPara haver crase, duas condições devem ser atendidas:\n1) A palavra ANTERIOR exige a preposição "a": "entregar" pede algo A alguém (entregar a notificação A alguém).\n2) A palavra SEGUINTE é feminina e admite o artigo "a": "A motorista" (uma mulher).\nTeste prático: troque por uma palavra masculina. "Entregou a notificação AO motorista" mostra que, se no masculino aparece "ao", no feminino é "à".\nObservação: se fosse um motorista homem, seria "ao motorista". O gênero da palavra determina a crase.'),
    q(T57, M57, 'E', 'No trecho “A fiscalização começou à partir das oito horas.”, o emprego do acento indicativo de crase está correto.',
      'Errado. NÃO há crase antes de VERBO, porque verbos não aceitam artigo.\n"Partir" é verbo (no infinitivo). Correto: "a partir das oito horas".\nOutros exemplos sem crase antes de verbo: "começou a chover", "estou disposto a ajudar", "a contar de hoje".\nCasos proibidos de crase (os mais cobrados): antes de verbo, antes de palavra masculina, antes da maioria dos pronomes (pessoais, de tratamento, indefinidos, demonstrativos "esta/essa"), entre palavras repetidas ("cara a cara") e antes de "a" no singular seguido de palavra no plural ("a pessoas").'),
    q(T57, M57, 'C', 'No trecho “O posto de atendimento funciona das 8h às 18h.”, o emprego do acento indicativo de crase está correto.',
      'Correto. Em indicação de horas, usa-se crase porque há preposição + artigo antes do numeral feminino ("as horas" subentendido).\nRegra do paralelismo nos intervalos:\n• "DAS 8h ÀS 18h": de + as / a + as → as duas pontas com artigo e preposição.\n• "DE 8h A 18h": as duas pontas sem artigo → sem crase.\nErro comum: misturar os padrões ("das 8h a 18h" ou "de 8h às 18h").\nOutras indicações de hora: "chegou às 7h", "à 1h" (uma hora é feminino singular), "Saiu às duas horas".'),
    q(T57, M57, 'E', 'No trecho “Os agentes viajaram à Brasília para o treinamento.”, o emprego do acento indicativo de crase está correto.',
      'Errado. "Brasília" é nome de cidade que NÃO admite artigo. Logo, não há crase.\nTeste prático (o famoso "vou a, volto da / volto de"):\n• "Volto DE Brasília" (sem artigo) → "Vou A Brasília" (sem crase).\n• "Volto DA Bahia" (com artigo) → "Vou À Bahia" (com crase).\n"Volto de, crase pra quê? Volto da, crase há!"\nExceção: se o nome da cidade vier ESPECIFICADO, aceita artigo e, portanto, crase: "Viajaram à Brasília dos anos 60", "Fui à Roma antiga".'),
    q(T57, M57, 'C', 'No trecho “Dirigir à noite exige atenção redobrada.”, o emprego do acento indicativo de crase está correto.',
      'Correto. Usa-se crase nas LOCUÇÕES ADVERBIAIS, PREPOSITIVAS e CONJUNTIVAS formadas por palavra FEMININA.\nLocuções adverbiais: à noite, à tarde, às pressas, às vezes, à vontade, às claras, à toa, à direita, à esquerda.\nLocuções prepositivas: à frente de, à custa de, à procura de, à espera de.\nLocuções conjuntivas: à medida que, à proporção que.\nNo trecho, "à noite" é locução adverbial de tempo, e a crase é obrigatória.\nAtenção: "a noite" sem crase também existe, mas como sujeito ou objeto ("A noite estava fria"; "Passei a noite em claro").'),
    q(T57, M57, 'E', 'No trecho “O motorista ficou frente à frente com o agente.”, o emprego do acento indicativo de crase está correto.',
      'Errado. NÃO há crase entre palavras REPETIDAS, porque entre elas aparece só a preposição, sem artigo.\nCorreto: "frente a frente".\nOutros exemplos: cara a cara, gota a gota, dia a dia, ponta a ponta, uma a uma, face a face, passo a passo.\nTeste: no masculino, "dia a dia" não vira "dia ao dia". Isso prova que não há artigo e, sem artigo, não há crase.'),
    q(T57, M57, 'C', 'No trecho “O relatório refere-se àquela ocorrência do fim de semana.”, o emprego do acento indicativo de crase está correto.',
      'Correto. Há crase quando a preposição "a" se funde com o "a" inicial dos pronomes demonstrativos "aquele(s)", "aquela(s)" e "aquilo".\na (preposição) + aquela = ÀQUELA\nO verbo "referir-se" exige a preposição "a" (refere-se A algo). Logo, "refere-se àquela ocorrência".\nTeste prático: troque por "este/esta". "Refere-se A ESTA ocorrência" mostra que existe a preposição e, portanto, cabe a crase com "aquela".\nOutros exemplos: "Assisti àquele filme"; "Não dei atenção àquilo"; "Obedeça àquelas normas".'),
    q(T57, M57, 'E', 'No trecho “A multa foi aplicada à todos os infratores.”, o emprego do acento indicativo de crase está correto.',
      'Errado. NÃO há crase antes de pronomes INDEFINIDOS (todos, todas, qualquer, cada, alguém, ninguém, nenhuma...), porque eles não admitem artigo.\nCorreto: "A multa foi aplicada A TODOS os infratores."\nReforço: "todos" é masculino, o que já impede a crase.\nExceções que admitem crase: "outra(s)" e "certa(s)", quando aceitam artigo ("Refiro-me à outra pessoa").'),
    q(T57, M57, 'C', 'No trecho “Após o plantão, o agente voltou a casa para descansar.”, a ausência do acento indicativo de crase está correta.',
      'Correto. A palavra "CASA", no sentido de LAR (a própria residência) e SEM determinante, não admite artigo. Por isso, não há crase.\n• "Voltou A CASA para descansar." (lar, sem especificação) → sem crase.\n• "Voltou À CASA DOS PAIS." (com especificador) → com crase, pois admite artigo.\nA mesma regra vale para "TERRA", no sentido de terra firme (oposto a bordo): "Os marinheiros desceram a terra" × "Voltei à terra natal".\nTeste: "Saí DE casa" (sem artigo) → "Voltei A casa"; "Saí DA casa dos pais" (com artigo) → "Voltei À casa dos pais".'),
    q(T57, M57, 'E', 'No trecho “Encaminho à Vossa Senhoria o relatório da operação.”, o emprego do acento indicativo de crase está correto.',
      'Errado. Os pronomes de TRATAMENTO iniciados por "Vossa" ou "Sua" (Vossa Senhoria, Vossa Excelência, Sua Majestade etc.) NÃO admitem artigo. Logo, não há crase.\nCorreto: "Encaminho A Vossa Senhoria o relatório da operação."\nExceções, que admitem artigo e, portanto, crase: "senhora", "senhorita", "dona" e "madame" (ex.: "Entreguei o documento à senhora").\nEsse é um ponto importantíssimo em redação oficial, muito presente em provas de concurso.'),

    /* ===== 5.8 Colocação pronominal ===== */
    q(T58, M58, 'C', 'No trecho “Não se admite estacionamento no acostamento.”, a próclise é obrigatória em razão da palavra negativa.',
      'Correto. A colocação pronominal trata da posição do pronome oblíquo átono (me, te, se, o, a, lhe, nos, vos...) em relação ao verbo:\n• Próclise: antes do verbo ("não SE admite").\n• Ênclise: depois do verbo ("admite-SE").\n• Mesóclise: no meio do verbo ("admitir-SE-á").\nPalavras NEGATIVAS (não, nunca, jamais, ninguém, nada, nem) são fatores de PRÓCLISE, ou seja, "atraem" o pronome para antes do verbo.\nPor isso, "Não SE admite" (e não "Não admite-se").\nOutros atrativos: pronomes relativos, conjunções subordinativas, advérbios (sem vírgula), pronomes indefinidos, frases interrogativas e exclamativas.'),
    q(T58, M58, 'E', 'No trecho “Me informaram que a pista estava interditada.”, a colocação pronominal está de acordo com a norma-padrão.',
      'Errado. A norma-padrão NÃO admite iniciar oração com pronome oblíquo átono. Nesse caso, usa-se a ÊNCLISE.\nCorreto: "Informaram-ME que a pista estava interditada."\nNo português do Brasil, "Me informaram..." é muito comum na fala e na escrita informal, mas em prova a norma-padrão prevalece.\nAtenção: esta regra vale também depois de pausa (vírgula, ponto e vírgula): "Quando cheguei, disseram-me que..."'),
    q(T58, M58, 'C', 'No trecho “Entregar-lhe-ei o relatório amanhã.”, a mesóclise está de acordo com a norma-padrão.',
      'Correto. A MESÓCLISE (pronome no meio do verbo) é usada com verbos no FUTURO DO PRESENTE ou no FUTURO DO PRETÉRITO, desde que não haja fator de próclise.\nComo se forma: separa-se o infinitivo da terminação do futuro e coloca-se o pronome entre eles.\nentregarei → entregar + lhe + ei → "Entregar-lhe-ei"\nentregaria → entregar + lhe + ia → "Entregar-lhe-ia"\nObservações:\n• Não se usa ênclise com futuro: "Entregarei-lhe" está errado.\n• Se houver fator de próclise, ela prevalece: "Não lhe entregarei o relatório."'),
    q(T58, M58, 'E', 'No trecho “O agente que atendeu-me foi muito cordial.”, a colocação pronominal está de acordo com a norma-padrão.',
      'Errado. O pronome RELATIVO "que" é fator de PRÓCLISE, ou seja, atrai o pronome oblíquo para antes do verbo.\nCorreto: "O agente QUE ME atendeu foi muito cordial."\nFatores de próclise mais cobrados:\n• Palavras negativas: não, nunca, ninguém.\n• Pronomes relativos: que, quem, o qual, cujo, onde.\n• Conjunções subordinativas: que, se, quando, embora, porque.\n• Advérbios (sem vírgula): aqui, já, sempre, ainda, talvez.\n• Pronomes indefinidos: tudo, todos, alguém, algo.'),
    q(T58, M58, 'C', 'No trecho “Aqui se fiscalizam todos os veículos de carga.”, a próclise está justificada pela presença do advérbio anteposto ao verbo, sem pausa.',
      'Correto. ADVÉRBIOS antepostos ao verbo, SEM pausa (sem vírgula), atraem o pronome oblíquo átono, exigindo a PRÓCLISE.\n"Aqui SE fiscalizam todos os veículos de carga."\nMas, se houver VÍRGULA depois do advérbio, a pausa "quebra" a atração, e volta-se à regra de não começar com pronome átono, usando-se a ênclise:\n"Aqui, fiscalizam-SE todos os veículos de carga."\nBônus de concordância: "fiscalizam-se" está no plural porque o "se" é apassivador e concorda com o sujeito paciente "todos os veículos" (= todos os veículos são fiscalizados).'),
    q(T58, M58, 'E', 'No trecho “Far-se-á a vistoria amanhã.”, a forma “Se fará a vistoria amanhã” seria a mais adequada à norma-padrão.',
      'Errado. A mesóclise "Far-se-á" é exatamente a forma recomendada pela norma-padrão. A alternativa proposta tem dois problemas:\n1) Inicia a oração com pronome oblíquo átono ("Se fará..."), o que a norma-padrão não admite.\n2) Com verbo no FUTURO DO PRESENTE e sem fator de próclise, a colocação prescrita é a MESÓCLISE.\nFormação: fará = far + á → far-SE-á.\nSe houvesse fator de próclise, aí sim: "Não SE fará a vistoria amanhã."'),
    q(T58, M58, 'C', 'No trecho “O motorista quer apresentar-se ao chefe do posto.”, a ênclise ao infinitivo na locução verbal está de acordo com a norma-padrão.',
      'Correto. Nas locuções verbais com INFINITIVO (ou gerúndio), sem fator de próclise, há mais de uma colocação correta:\n• Ênclise ao infinitivo: "O motorista quer apresentar-SE ao chefe." (a do trecho)\n• Ênclise ao auxiliar: "O motorista quer-SE apresentar ao chefe."\n• Próclise ao infinitivo, sem hífen (aceita no português brasileiro): "O motorista quer SE apresentar ao chefe."\nCom fator de próclise, o pronome pode vir antes do auxiliar ou depois do infinitivo: "O motorista não SE quer apresentar" / "O motorista não quer apresentar-SE".'),
    q(T58, M58, 'E', 'No trecho “Tudo esclareceu-se após a perícia.”, a colocação pronominal está de acordo com a norma-padrão.',
      'Errado. Os pronomes INDEFINIDOS (tudo, todos, nada, alguém, ninguém, algo, qualquer...) são fatores de PRÓCLISE.\nCorreto: "TUDO SE esclareceu após a perícia."\nPor que isso acontece? Os indefinidos são palavras com forte carga de sentido que "puxam" o pronome átono para perto de si.\nOutros exemplos: "Todos ME cumprimentaram"; "Alguém TE ligou"; "Nada SE perdeu".'),
    q(T58, M58, 'C', 'No trecho “Espero que me avisem com antecedência sobre a interdição.”, a próclise é exigida pela conjunção subordinativa.',
      'Correto. As conjunções SUBORDINATIVAS (que, se, quando, embora, porque, caso, conforme...) são fatores de PRÓCLISE.\nNo trecho, "que" é conjunção subordinativa integrante (introduz a oração "que me avisem com antecedência", objeto direto de "espero").\nPor isso: "Espero QUE ME avisem" (e não "que avisem-me").\nOutros exemplos: "Quando SE aproximou da barreira, reduziu a velocidade"; "Embora O conhecesse, não o cumprimentou"; "Se ME chamarem, irei".'),
    q(T58, M58, 'E', 'A ênclise ao particípio, como em “Os agentes tinham avisado-o do bloqueio”, é admitida pela norma-padrão.',
      'Errado. A norma-padrão NÃO admite ÊNCLISE ao PARTICÍPIO. Formas como "avisado-o", "feito-lhe" ou "dado-me" são sempre inadequadas.\nNos tempos compostos (ter/haver + particípio), o pronome se liga ao VERBO AUXILIAR:\n• Sem fator de próclise: "Os agentes tinham-NO avisado do bloqueio." (o "o" vira "no" depois de forma verbal terminada em som nasal)\n• Com fator de próclise: "Os agentes não O tinham avisado."\n• No português brasileiro também se aceita: "Os agentes tinham O avisado" (próclise ao particípio).\nLembrete das transformações: depois de som nasal (-am, -em, -ão, -õe), o/a/os/as viram no/na/nos/nas; depois de r/s/z, que caem, viram lo/la/los/las ("avisá-lo").'),

    /* ===== 6.1 Significação das palavras ===== */
    q(T61, M6, 'C', 'No trecho “O agente agiu com discrição ao abordar o suspeito.”, a palavra “discrição” significa reserva, prudência, e não se confunde com “descrição”, ato de descrever.',
      'Correto. Este é um caso de PARONÍMIA. Parônimos são palavras de grafia e pronúncia PARECIDAS, mas com significados DIFERENTES.\n• DISCRIÇÃO (com "i"): reserva, prudência, qualidade de quem é discreto. "O agente agiu com discrição."\n• DESCRIÇÃO (com "e"): ato de descrever. "A descrição do suspeito ajudou na busca."\nDica de memorização: dIscrIção → dIscreto (os dois com "i").\nOutros parônimos clássicos: eminente/iminente, ratificar/retificar, infringir/infligir, deferir/diferir, comprimento/cumprimento, flagrante/fragrante, mandato/mandado.'),
    q(T61, M6, 'E', 'No trecho “O chefe do posto decidiu ratificar o erro constante do boletim.”, o verbo “ratificar” foi empregado adequadamente no sentido de corrigir.',
      'Errado. "Ratificar" e "retificar" são parônimos frequentemente confundidos.\n• RAtificar: CONFIRMAR, validar, reafirmar. "O diretor ratificou a decisão da equipe."\n• REtificar: CORRIGIR, consertar, endireitar. "O chefe retificou o erro do boletim."\nComo o trecho fala de corrigir um erro, o verbo adequado seria "retificar".\nMacete: "REtificar" = "REto" (deixar reto, corrigir); "RAtificar" = "RAtificar o que já foi dito" (confirmar).'),
    q(T61, M6, 'C', 'No trecho “O condutor foi preso em flagrante.”, a palavra “flagrante” indica o ato surpreendido no momento em que é praticado e não se confunde com “fragrante”, que significa perfumado.',
      'Correto. Mais um par de parônimos:\n• FLAGRANTE: evidente, manifesto; ato surpreendido no momento em que é praticado. No Direito, "prisão em flagrante" é a prisão de quem é pego cometendo o crime ou logo após.\n• FRAGRANTE: perfumado, aromático (de "fragrância").\nOu seja: "Preso em flagrante" (e nunca "em fragrante"). "Flores fragrantes" (perfumadas).\nDica: FRAGRANTE tem o mesmo "fra" de FRAgrância.'),
    q(T61, M6, 'E', 'No trecho “O diretor deferiu o pedido de remoção do servidor.”, o verbo “deferiu” significa que o pedido foi negado.',
      'Errado. "Deferir" significa ATENDER, CONCEDER, APROVAR o que foi pedido. O oposto é "INdeferir" (negar).\n• "O diretor deferiu o pedido" → o pedido foi CONCEDIDO.\n• "O diretor indeferiu o pedido" → o pedido foi NEGADO.\nAtenção a outro parônimo: "DIferir" significa ADIAR ou DIVERGIR, ser diferente ("O pagamento foi diferido"; "As opiniões diferem").\nEsses termos aparecem muito na linguagem administrativa e jurídica, então são essenciais para quem vai ser servidor público.'),
    q(T61, M6, 'C', 'No trecho “A imprudência do condutor causou o acidente.”, o prefixo “im-”, em “imprudência”, tem valor de negação.',
      'Correto. O prefixo latino "in-" (com as variantes "im-", antes de "p" e "b", e "i-", antes de "l", "m", "n" e "r") expressa NEGAÇÃO ou PRIVAÇÃO.\n• imprudência = ausência de prudência\n• ilegal = não legal\n• incapaz = não capaz\n• irregular = não regular\n• impaciente, imbatível, inútil...\nCuidado: em algumas palavras, "in-" indica movimento para dentro (importar, ingerir, inserir), um prefixo homônimo com outro sentido. O contexto e a análise da palavra ajudam a distinguir.'),
    q(T61, M6, 'E', 'No trecho “O risco de colisão era iminente.”, a palavra “iminente” significa notável, ilustre.',
      'Errado. Outro par de parônimos muito cobrado:\n• IMINENTE (com "i"): PRESTES A ACONTECER, imediato, próximo. "O risco de colisão era iminente."\n• EMINENTE (com "e"): NOTÁVEL, ILUSTRE, elevado. "O eminente jurista proferiu a palestra."\nNo trecho, o sentido é de risco prestes a se concretizar. Portanto, "iminente" está bem empregado, mas significa algo diferente do que o item diz.\nMacete: Iminente = Imediato (ambos com "I"); Eminente = Elevado, Excelente (todos com "E").'),
    q(T61, M6, 'C', 'Nos trechos “O motorista perdeu a direção do veículo na curva” e “A direção do órgão divulgou nota oficial”, a palavra “direção” assume sentidos distintos, o que exemplifica a polissemia.',
      'Correto. POLISSEMIA é a propriedade de uma MESMA palavra apresentar VÁRIOS significados, que são determinados pelo contexto.\nNo trecho:\n• "perdeu a DIREÇÃO do veículo" → controle do volante, condução.\n• "A DIREÇÃO do órgão divulgou nota" → chefia, administração, gestão.\nOutros sentidos possíveis: rumo, sentido ("na direção norte"), o volante do carro ("direção hidráulica").\nNão confunda polissemia (uma palavra, sentidos relacionados) com homonímia (palavras diferentes que coincidem na forma, como "são" de santo, "são" de saudável e "são" do verbo ser).'),
    q(T61, M6, 'E', 'Os verbos “infringir” e “infligir” são sinônimos, de modo que o trecho “O condutor infligiu a lei de trânsito” está adequado quanto ao sentido.',
      'Errado. "Infringir" e "infligir" são PARÔNIMOS, e não sinônimos:\n• INFRINGIR: TRANSGREDIR, VIOLAR, desrespeitar (uma lei, norma ou regra). "O condutor infringiu a lei de trânsito." Daí vem "infração".\n• INFLIGIR: APLICAR (pena, castigo, sofrimento). "O agente infligiu multa ao condutor."\nO trecho deveria usar "infringiu".\nMacete: infRingir → Regra (quebrar a Regra); infLigir → apLicar (aplicar a pena).'),
    q(T61, M6, 'C', 'No trecho “Após o temporal, a rodovia virou um rio.”, a palavra “rio” foi empregada em sentido conotativo.',
      'Correto. A palavra está em sentido CONOTATIVO (figurado), e não DENOTATIVO (literal).\n• Sentido denotativo de "rio": curso natural de água doce que corre em um leito.\n• Sentido conotativo no trecho: a rodovia ficou tão alagada que PARECIA um rio.\nTrata-se de uma METÁFORA: uma comparação implícita, sem conectivo comparativo ("como", "feito"). Se fosse "a rodovia virou como um rio", seria comparação (símile).\nLinguagem conotativa é comum em textos literários, publicitários e na fala cotidiana; textos técnicos e oficiais preferem a denotativa.'),
    q(T61, M6, 'E', 'No trecho “Os agentes cumprimentaram o comandante ao início do turno.”, o verbo “cumprimentar” significa executar, cumprir uma determinação.',
      'Errado. "Cumprimentar" significa SAUDAR (dar bom-dia, apertar a mão, felicitar).\nO sentido de EXECUTAR, cumprir uma ordem, é expresso pelo verbo "CUMPRIR": "Os agentes cumpriram a determinação."\nCuidado extra com os substantivos:\n• CUMPRIMENTO: saudação ("Receba meus cumprimentos") ou execução ("o cumprimento da lei").\n• COMPRIMENTO: extensão, medida ("o comprimento da ponte").\nNo trecho, o sentido é de saudação.'),

    /* ===== 6.2 Substituição de palavras ou trechos ===== */
    q(T62, M6, 'C', 'No trecho “A operação foi suspensa devido à forte chuva.”, a substituição de “devido à” por “em razão da” preservaria a correção gramatical e o sentido original.',
      'Correto. "Devido a" e "em razão de" são locuções prepositivas de valor CAUSAL. Ambas introduzem o motivo de algo.\n"A operação foi suspensa devido à forte chuva" = "A operação foi suspensa em razão da forte chuva."\nRepare na adaptação: "devido À" (a + a, crase) passa a "em razão DA" (de + a). A troca mantém a correção porque a nova locução também traz sua preposição.\nOutras locuções causais equivalentes: por causa de, em virtude de, em decorrência de, em função de, graças a (geralmente para causas positivas).'),
    q(T62, M6, 'E', 'No trecho “Conquanto houvesse sinalização, o motorista não reduziu a velocidade.”, a substituição de “Conquanto” por “Visto que” preservaria o sentido original.',
      'Errado. Os dois conectores pertencem a grupos diferentes:\n• CONQUANTO: conjunção CONCESSIVA (= embora, ainda que, se bem que). Indica um fato que não impediu o outro: havia sinalização, MESMO ASSIM o motorista não reduziu.\n• VISTO QUE: conjunção CAUSAL (= porque, já que, uma vez que). Indicaria a sinalização como CAUSA de não reduzir, o que é ilógico.\nHá também um problema de modo verbal: a concessiva pede SUBJUNTIVO ("houvesse"); a causal pede INDICATIVO ("havia").\nSubstitutos corretos de "Conquanto": Embora, Ainda que, Mesmo que, Posto que, Se bem que.'),
    q(T62, M6, 'C', 'No trecho “O agente pediu ao motorista que desligasse o motor.”, a substituição de “ao motorista” por “lhe”, com a forma “O agente pediu-lhe que desligasse o motor”, preservaria a correção gramatical.',
      'Correto. Para substituir um complemento por pronome, primeiro identifique a função sintática.\nO verbo "pedir" é transitivo direto e indireto: pede-se ALGO (objeto direto) A ALGUÉM (objeto indireto).\n• "ao motorista" → objeto INDIRETO (com preposição "a"), referente a pessoa.\n• "que desligasse o motor" → objeto DIRETO (oração).\nO pronome que substitui objeto indireto de pessoa é "LHE". Logo: "O agente pediu-LHE que desligasse o motor."\nÊnclise correta: não há fator de próclise e o verbo está no pretérito perfeito ("pediu-lhe").'),
    q(T62, M6, 'E', 'No trecho “O agente encontrou o motorista no posto.”, a substituição de “o motorista” por “lhe”, resultando em “O agente encontrou-lhe no posto”, preservaria a correção gramatical.',
      'Errado. "Encontrar" é verbo TRANSITIVO DIRETO: quem encontra, encontra ALGUÉM (sem preposição). Então "o motorista" é OBJETO DIRETO.\nOs pronomes oblíquos têm funções diferentes:\n• O, A, OS, AS → substituem OBJETO DIRETO: "O agente encontrou-O no posto."\n• LHE, LHES → substituem OBJETO INDIRETO (de pessoa): "O agente entregou-LHE a multa" (entregou a ele).\nUsar "lhe" no lugar de objeto direto ("encontrou-lhe") é erro muito comum e muito cobrado.\nTeste: se o verbo pede preposição "a" (dar a, entregar a, pedir a), use "lhe". Se não pede, use "o/a".'),
    q(T62, M6, 'C', 'No trecho “É necessário que se respeitem os limites de velocidade.”, a reescrita “É necessário respeitar os limites de velocidade” preservaria a correção gramatical e o sentido original.',
      'Correto. A oração "que se respeitem os limites de velocidade" é desenvolvida (com conjunção e verbo flexionado). Ela pode ser REDUZIDA DE INFINITIVO: "respeitar os limites de velocidade".\nEm ambas as versões, a obrigação é GENÉRICA (não se especifica quem deve respeitar), e a oração continua sendo sujeito de "É necessário".\n• "É necessário que se respeitem os limites" ("se" apassivador: os limites sejam respeitados).\n• "É necessário respeitar os limites" (infinitivo impessoal).\nO sentido e a correção gramatical são preservados.'),
    q(T62, M6, 'E', 'No trecho “Os motoristas devem redobrar a atenção, porquanto a pista é estreita.”, a substituição de “porquanto” por “porém” preservaria o sentido original.',
      'Errado. "PORQUANTO" é conjunção de valor CAUSAL/EXPLICATIVO (= porque, pois, visto que, uma vez que). "PORÉM" é ADVERSATIVA (= mas, contudo).\nOriginal: os motoristas devem redobrar a atenção PORQUE a pista é estreita (a pista estreita é o motivo).\nCom "porém": "devem redobrar a atenção, PORÉM a pista é estreita". Haveria oposição, sem lógica, e o sentido muda totalmente.\nDica: "porquanto" lembra "porque" (POR...). É uma palavra formal que a banca usa para testar se o candidato conhece seu valor.'),
    q(T62, M6, 'C', 'No trecho “A interdição ocorreu em virtude de obras na ponte.”, a substituição de “em virtude de” por “por causa de” preservaria a correção gramatical e o sentido original.',
      'Correto. "Em virtude de" e "por causa de" são LOCUÇÕES PREPOSITIVAS de valor CAUSAL e podem ser trocadas entre si.\n"A interdição ocorreu em virtude de obras na ponte" = "A interdição ocorreu por causa de obras na ponte."\nAmbas indicam o motivo da interdição. A correção se mantém porque as duas terminam com a preposição "de" e regem o mesmo tipo de complemento ("obras na ponte").\nOutras equivalentes: devido a, em razão de, em decorrência de, em função de.'),
    q(T62, M6, 'E', 'No trecho “Há dois anos a rodovia foi asfaltada.”, a substituição de “Há” por “A” preservaria a correção gramatical e o sentido original.',
      'Errado. "HÁ" e "A" em expressões de tempo têm sentidos opostos:\n• HÁ (verbo haver) → TEMPO PASSADO, decorrido: "Há dois anos a rodovia foi asfaltada" (= faz dois anos).\n• A (preposição) → TEMPO FUTURO ou DISTÂNCIA: "Daqui a dois anos a rodovia será duplicada"; "O posto fica a dois quilômetros".\nTrocando "Há" por "A", a frase fica incorreta e perde o sentido de passado.\nDica: se der para trocar por "FAZ", use "HÁ" ("Faz dois anos" → "Há dois anos"). Atenção também à redundância "Há dois anos atrás", que deve ser evitada.'),
    q(T62, M6, 'C', 'No trecho “O condutor, cujo veículo estava irregular, foi orientado pelos agentes.”, a substituição de “cujo veículo estava irregular” por “que estava com o veículo irregular” preservaria a correção gramatical e o sentido original.',
      'Correto. O pronome relativo "CUJO" indica POSSE e sempre fica entre dois substantivos: o possuidor (antecedente) e a coisa possuída.\n"O condutor, CUJO veículo estava irregular" = o veículo DO condutor estava irregular.\nA reescrita "que estava com o veículo irregular" mantém:\n• a relação de posse (o condutor está com o veículo dele);\n• o caráter explicativo (oração entre vírgulas);\n• a correção gramatical.\nLembretes sobre "cujo": concorda com a coisa possuída (cujo veículo, cuja moto, cujos documentos) e NUNCA é seguido de artigo ("cujo O veículo" é erro).'),
    q(T62, M6, 'E', 'No trecho “O posto onde trabalho fica às margens da rodovia.”, a substituição de “onde” por “aonde” preservaria a correção gramatical.',
      'Errado. A diferença entre "ONDE" e "AONDE" depende da regência do verbo:\n• AONDE (a + onde) → verbos de MOVIMENTO que pedem a preposição "a": ir, chegar, levar, dirigir-se. "Aonde você vai?" (vai A algum lugar).\n• ONDE → verbos de PERMANÊNCIA, de estado: estar, ficar, morar, trabalhar. "Onde você trabalha?" (trabalha EM algum lugar).\n"Trabalhar" indica permanência. Logo: "O posto ONDE trabalho".\nHá ainda "DONDE" (de + onde), com verbos que indicam procedência: "Donde vens?".'),

    /* ===== 6.3 Reorganização de orações e períodos ===== */
    q(T63, M6, 'C', 'A reescrita do período “A PRF apreendeu a carga.” na forma “A carga foi apreendida pela PRF.” preserva o sentido e a correção gramatical original.',
      'Correto. Na transformação da voz ATIVA para a PASSIVA ANALÍTICA:\n1) O OBJETO DIRETO da ativa ("a carga") vira SUJEITO PACIENTE.\n2) O SUJEITO da ativa ("A PRF") vira AGENTE DA PASSIVA (introduzido por "por/pelo/pela").\n3) O verbo vira locução: SER (no mesmo tempo do verbo original) + PARTICÍPIO.\nAtiva: "A PRF APREENDEU a carga." (pretérito perfeito)\nPassiva: "A carga FOI APREENDIDA pela PRF." ("foi" = ser no pretérito perfeito)\nAtenção: o particípio concorda com o sujeito paciente ("apreendidA", porque "carga" é feminino).\nSó verbos transitivos diretos admitem voz passiva.'),
    q(T63, M6, 'E', 'A reescrita do período “Os agentes fiscalizarão os caminhões.” na forma “Os caminhões foram fiscalizados pelos agentes.” preserva o tempo verbal e o sentido original.',
      'Errado. Na passagem para a voz passiva, o verbo auxiliar SER deve ficar no MESMO TEMPO e MODO do verbo da ativa.\n• Ativa: "fiscalizarão" → FUTURO DO PRESENTE.\n• Passiva correta: "Os caminhões SERÃO fiscalizados pelos agentes" ("serão" = futuro do presente).\n• O item usa "FORAM fiscalizados" → pretérito perfeito. Muda o tempo: o que ia acontecer passa a ter acontecido.\nTabela útil: fiscaliza → é fiscalizado; fiscalizou → foi fiscalizado; fiscalizava → era fiscalizado; fiscalizará → será fiscalizado; fiscalizaria → seria fiscalizado.'),
    q(T63, M6, 'C', 'A reescrita do período “Embora chovesse, a operação ocorreu.” na forma “Chovia, mas a operação ocorreu.” preserva o sentido original e a correção gramatical.',
      'Correto. A mesma relação de sentido pode ser expressa por estruturas sintáticas diferentes.\n• Original (subordinação concessiva): "EMBORA chovesse, a operação ocorreu."\n• Reescrita (coordenação adversativa): "Chovia, MAS a operação ocorreu."\nNas duas, a ideia é a mesma: a chuva era um obstáculo que NÃO impediu a operação.\nRepare no ajuste do modo verbal: "embora" pede subjuntivo ("chovesse"); com "mas", usa-se o indicativo ("chovia"). A reescrita fez a adaptação corretamente.\nDica: concessão e adversidade são "primas", e o Cebraspe frequentemente pede essa conversão.'),
    q(T63, M6, 'E', 'A reescrita do período “Como a pista estava interditada, os motoristas usaram o desvio.” na forma “A pista estava interditada porque os motoristas usaram o desvio.” preserva o sentido original.',
      'Errado. A reescrita INVERTE a relação de causa e consequência.\n• Original: CAUSA = a pista estava interditada; CONSEQUÊNCIA = os motoristas usaram o desvio.\n• Reescrita do item: "A pista estava interditada PORQUE os motoristas usaram o desvio" faz do uso do desvio a causa da interdição. Absurdo lógico!\nReescrita fiel: "Os motoristas usaram o desvio PORQUE a pista estava interditada."\nLembre-se: "COMO" no início da frase, com valor causal, equivale a "porque", "já que", "visto que", mas introduz sempre a CAUSA.'),
    q(T63, M6, 'C', 'A reescrita do período “Durante a madrugada, a equipe realizou a vistoria.” na forma “A equipe realizou a vistoria durante a madrugada.” preserva o sentido original e a correção gramatical.',
      'Correto. O adjunto adverbial ("Durante a madrugada", indicando tempo) tem MOBILIDADE na oração: pode vir no início, no meio ou no fim.\n• No início: "Durante a madrugada, a equipe realizou a vistoria." (vírgula facultativa por ser curto)\n• No fim (posição natural, ordem direta): "A equipe realizou a vistoria durante a madrugada." (sem vírgula)\n• No meio: "A equipe, durante a madrugada, realizou a vistoria." (vírgulas obrigatórias)\nO sentido não muda; só a ênfase. A pontuação acompanha a posição.'),
    q(T63, M6, 'E', 'A reescrita do período “Fiscalizaram-se os veículos.” na forma “Os veículos fiscalizaram.” preserva o sentido original.',
      'Errado. O original está na VOZ PASSIVA SINTÉTICA, formada por verbo transitivo direto + "se" apassivador.\n"Fiscalizaram-se os veículos" = "Os veículos FORAM FISCALIZADOS" (por alguém, como os agentes). Os veículos SOFRERAM a ação.\nNa reescrita "Os veículos fiscalizaram", os veículos passam a PRATICAR a ação de fiscalizar. É um absurdo semântico, e a frase ainda fica sem objeto (fiscalizaram o quê?).\nReescrita correta: "Os veículos foram fiscalizados" (passiva analítica).\nDica: para conferir se o "se" é apassivador, transforme na passiva analítica (ser + particípio). Se der certo, o "se" é apassivador.'),
    q(T63, M6, 'C', 'Os períodos “O motorista estava cansado. Ele parou no posto para descansar.” podem ser reunidos em “Por estar cansado, o motorista parou no posto para descansar.”, sem prejuízo do sentido e da correção gramatical.',
      'Correto. Entre os dois períodos originais existe uma relação de CAUSA implícita: ele parou PORQUE estava cansado.\nA reescrita torna essa relação explícita com uma oração REDUZIDA DE INFINITIVO introduzida pela preposição "Por", de valor causal:\n"POR ESTAR cansado, o motorista parou..." = "COMO estava cansado, o motorista parou..." = "O motorista parou PORQUE estava cansado".\nAlém disso, a reescrita elimina o pronome "Ele", que deixa de ser necessário, já que o sujeito "o motorista" vale para as duas orações.\nEsse tipo de item (unir períodos sem prejuízo do sentido) é muito comum no Cebraspe.'),
    q(T63, M6, 'E', 'A reescrita do período “Se o condutor tivesse parado, não seria autuado.” na forma “Como o condutor parou, não foi autuado.” preserva o sentido original.',
      'Errado. A reescrita transforma uma HIPÓTESE em FATO, e com sentido contrário.\n• Original: "Se o condutor TIVESSE PARADO, não SERIA autuado." É hipótese irreal (contrária aos fatos). Subentende-se que o condutor NÃO parou e FOI autuado.\n• Reescrita: "Como o condutor PAROU, não FOI autuado." Afirma como real que ele parou e não foi autuado.\nOs fatos ficam exatamente invertidos.\nLembre-se: "se" + mais-que-perfeito do subjuntivo ("tivesse parado") + futuro do pretérito ("seria") indica algo que NÃO aconteceu.'),
    q(T63, M6, 'C', 'A passagem do discurso direto “O agente disse: — Liberarei a pista amanhã.” para o indireto, na forma “O agente disse que liberaria a pista no dia seguinte.”, está correta.',
      'Correto. Na passagem do discurso DIRETO para o INDIRETO, fazem-se ajustes sistemáticos:\n1) PESSOA: 1ª pessoa → 3ª pessoa ("Liberarei" [eu] → "liberaria" [ele]).\n2) TEMPO VERBAL: futuro do presente → futuro do pretérito ("liberarei" → "liberaria").\n3) ADVÉRBIOS de tempo e lugar: "amanhã" → "no dia seguinte"; "hoje" → "naquele dia"; "aqui" → "ali/lá"; "ontem" → "no dia anterior".\n4) Introdução de conjunção integrante ("que") e eliminação de travessão e dois-pontos.\nOutras correspondências: presente → imperfeito ("estou" → "estava"); pretérito perfeito → mais-que-perfeito ("vi" → "tinha visto"); imperativo → imperfeito do subjuntivo ("Pare!" → "que parasse").'),
    q(T63, M6, 'E', 'A passagem do discurso direto “O motorista afirmou: — Eu não vi a placa.” para o indireto, na forma “O motorista afirmou que eu não tinha visto a placa.”, está correta.',
      'Errado. No discurso indireto, quem conta a história é o narrador. Por isso, a 1ª pessoa do falante (eu) deve passar à 3ª pessoa (ele).\n• Correto: "O motorista afirmou que (ELE) não tinha visto a placa."\n• Errado (como no item): "O motorista afirmou que EU não tinha visto a placa." Assim, quem não viu a placa passa a ser o narrador, e não o motorista.\nO tempo verbal está bem ajustado no item ("vi" → "tinha visto", pretérito perfeito → mais-que-perfeito). O erro está apenas na pessoa, mas é suficiente para alterar o sentido.'),

    /* ===== 6.4 Reescrita em diferentes gêneros e níveis de formalidade ===== */
    q(T64, M6, 'C', 'A reescrita do trecho “A gente vai dar um jeito na estrada.” na forma “Providenciaremos a recuperação da rodovia.” torna o texto adequado a um registro formal, como o de uma nota oficial.',
      'Correto. O item trata da adequação do texto ao REGISTRO (nível de formalidade) exigido pelo gênero.\nMarcas de informalidade no original:\n• "A gente": locução pronominal coloquial (equivale a "nós").\n• "vai dar um jeito": expressão coloquial e vaga.\n• "estrada": termo comum, menos técnico que "rodovia".\nNa reescrita formal:\n• Verbo na 1ª pessoa do plural ("Providenciaremos"), no futuro do presente.\n• Termos precisos e institucionais ("recuperação da rodovia").\nO resultado é adequado a uma nota oficial: claro, formal e conforme a norma-padrão.'),
    q(T64, M6, 'E', 'Em um ofício dirigido a um cidadão, a reescrita de “Vossa Senhoria deverá comparecer ao posto” como “Você tem que vir no posto” seria adequada ao nível de formalidade do documento.',
      'Errado. O ofício é documento OFICIAL e exige linguagem FORMAL e NORMA-PADRÃO. A reescrita proposta tem várias inadequações:\n1) "Você": pronome informal, em vez do tratamento adequado "Vossa Senhoria".\n2) "tem que": construção coloquial; no registro formal prefere-se "deverá" ou "tem de".\n3) "vir NO posto": desvio de regência, já que verbos de movimento pedem a preposição "a" ("vir AO posto").\nO original "Vossa Senhoria deverá comparecer ao posto" está perfeitamente adequado.'),
    q(T64, M6, 'C', 'Em uma nota oficial, a reescrita de “Tá liberado o trânsito na BR.” como “Está liberado o trânsito na rodovia.” adequaria o trecho ao registro formal, eliminando marca de oralidade.',
      'Correto. "Tá" é a forma reduzida de "está", típica da ORALIDADE informal.\nEm textos formais (nota oficial, ofício, relatório), deve-se usar a forma plena: "Está liberado o trânsito na rodovia."\nA reescrita também trocou "BR" (sigla usada informalmente) por "rodovia", termo mais adequado ao registro formal. Em textos técnicos, a identificação completa seria ainda mais precisa (ex.: "BR-116").\nOutras marcas de oralidade a evitar na escrita formal: "pra" (para), "tô" (estou), "né" (não é), "cê" (você), "aí" (como conector).'),
    q(T64, M6, 'E', 'Em textos formais destinados ao público, o uso de gírias e de expressões coloquiais é recomendado para aproximar o órgão do cidadão.',
      'Errado. Textos formais destinados ao público, especialmente os institucionais, devem seguir a NORMA-PADRÃO.\nGírias e expressões coloquiais:\n• comprometem a formalidade e a credibilidade institucional;\n• podem prejudicar a clareza (nem todos conhecem as mesmas gírias, que variam por região e por geração);\n• envelhecem rapidamente.\nA aproximação com o cidadão deve ser feita com linguagem SIMPLES e CLARA (frases curtas, palavras de uso comum, sem jargões), o que é diferente de linguagem INFORMAL.\nEsse é o princípio da chamada "linguagem simples", cada vez mais adotado pelos órgãos públicos.'),
    q(T64, M6, 'C', 'A redação “A PRF informou que a rodovia foi liberada às 14h.” é adequada ao gênero notícia, por apresentar o fato de forma objetiva, em terceira pessoa e com indicação da fonte.',
      'Correto. A redação apresenta as marcas típicas do gênero NOTÍCIA:\n• OBJETIVIDADE: relata o fato sem opinião ou adjetivação valorativa.\n• TERCEIRA PESSOA: o redator não se coloca no texto.\n• ATRIBUIÇÃO À FONTE: "A PRF informou que...". A informação é creditada a quem a forneceu, o que dá credibilidade e isenção ao jornalista.\n• PRECISÃO: indicação de horário ("às 14h").\nObservação: o verbo "informou" é neutro. Verbos como "admitiu", "alegou" ou "confessou" já trariam carga avaliativa.'),
    q(T64, M6, 'E', 'A reescrita do trecho “Aí o cara bateu no poste.” na forma “Então, o condutor colidiu com o poste.” mantém o mesmo nível de informalidade do original.',
      'Errado. A reescrita NÃO mantém o nível de informalidade; ela o ELEVA significativamente.\nSubstituições feitas:\n• "Aí" (marcador conversacional da fala) → "Então" (conector mais neutro, seguido de vírgula).\n• "o cara" (gíria) → "o condutor" (termo técnico/formal).\n• "bateu no" (coloquial) → "colidiu com" (vocabulário formal e regência adequada).\nO sentido essencial é preservado, mas o REGISTRO muda de informal para formal. O item erra ao dizer que o nível é o mesmo.'),
    q(T64, M6, 'C', 'A reescrita do trecho “Pegaram o motorista com carga roubada.” na forma “O motorista foi flagrado transportando carga roubada.” torna o texto mais formal, preservando seu sentido essencial.',
      'Correto. A reescrita aumenta a formalidade preservando a informação:\n• "Pegaram" (verbo coloquial, sujeito indeterminado na 3ª pessoa do plural) → "foi flagrado" (voz passiva, verbo preciso e formal).\n• "com carga roubada" → "transportando carga roubada" (especifica a situação).\nEm ambas as versões, quem realizou a ação permanece indeterminado; a passiva sem agente mantém essa característica.\nO sentido essencial (o motorista foi surpreendido com carga roubada) é preservado.'),
    q(T64, M6, 'E', 'A adequação ao nível de formalidade é exigência exclusiva dos textos escritos, não se aplicando à comunicação oral em situações solenes.',
      'Errado. A adequação ao nível de formalidade depende da SITUAÇÃO COMUNICATIVA (quem fala, com quem, onde, com que finalidade), e não da modalidade, escrita ou oral.\nSituações orais que exigem registro formal: discursos, audiências judiciais, sessões legislativas, cerimônias de posse, entrevistas de emprego, palestras, depoimentos.\nSituações escritas que admitem informalidade: mensagens entre amigos, bilhetes, posts pessoais.\nOu seja, existe fala formal e escrita informal. O item erra ao restringir a exigência aos textos escritos.'),
    q(T64, M6, 'C', 'A reescrita do convite informal “Pessoal, bora na reunião amanhã?” na forma “Convidamos os servidores a participar da reunião de amanhã.” é adequada a uma comunicação institucional.',
      'Correto. A reescrita adapta o convite ao contexto institucional:\n• "Pessoal" (vocativo informal) → "os servidores" (designação adequada).\n• "bora" (gíria, redução de "vamos embora") → "Convidamos ... a participar" (verbo formal).\n• "na reunião" (regência coloquial: "ir em") → "da reunião" (regência adequada de "participar de").\n• Pergunta informal → afirmação formal e impessoal.\nO resultado é compatível com uma comunicação oficial interna.'),
    q(T64, M6, 'E', 'A reescrita do trecho “O motorista disse que tava sem grana pra pagar o pedágio.” na forma “O motorista declarou não dispor de recursos para pagar o pedágio.” altera o sentido original.',
      'Errado. A reescrita NÃO altera o sentido. Ela apenas eleva o nível de formalidade.\nSubstituições:\n• "disse" → "declarou" (verbo mais formal com mesmo sentido).\n• "tava sem grana" → "não dispor de recursos" (registro formal).\n• "pra" → "para" (forma plena).\n• A oração desenvolvida "que tava" virou reduzida de infinitivo ("não dispor").\nO conteúdo informado (o motorista não tinha dinheiro para o pedágio) permanece o mesmo. O item erra ao afirmar mudança de sentido.\nDica de prova: diferencie mudança de REGISTRO (formalidade) de mudança de SENTIDO (informação).'),

    /* ===== 7.1 Aspectos gerais da redação oficial ===== */
    q(T71, M7, 'C', 'Segundo o Manual de Redação da Presidência da República (3ª edição, 2018), a redação oficial deve caracterizar-se, entre outros atributos, por clareza, concisão, impessoalidade, formalidade e padronização, além do uso da norma-padrão da língua.',
      'Correto. O Manual de Redação da Presidência da República (MRPR, 3ª ed., 2018) lista os atributos da redação oficial:\n1) Clareza e precisão.\n2) Objetividade.\n3) Concisão.\n4) Coesão e coerência.\n5) Impessoalidade.\n6) Formalidade e padronização.\n7) Uso da norma-padrão da língua portuguesa.\nO item cita alguns deles corretamente ("entre outros atributos").\nPor que isso importa? A redação oficial é a forma como o Poder Público se comunica. Ela deve ser compreensível para qualquer cidadão, uniforme e despida de marcas pessoais, em respeito ao princípio constitucional da impessoalidade (art. 37 da CF).'),
    q(T71, M7, 'E', 'Em atenção à impessoalidade, admite-se que o texto oficial expresse impressões e opiniões individuais do servidor que o redige, desde que este se identifique ao final.',
      'Errado. A IMPESSOALIDADE significa que a comunicação é feita em nome do SERVIÇO PÚBLICO, e não do servidor como indivíduo.\nPor isso, o texto oficial deve:\n• evitar impressões e opiniões pessoais do redator;\n• dirigir-se ao destinatário de forma impessoal, como cidadão ou instituição;\n• tratar do assunto de forma objetiva, sem "toque pessoal".\nA identificação do signatário no fim do documento não autoriza a inclusão de opiniões pessoais. Ela apenas indica a autoridade responsável pela comunicação.\nA impessoalidade decorre diretamente do princípio da impessoalidade da Administração Pública (art. 37, caput, CF).'),
    q(T71, M7, 'C', 'A concisão, na redação oficial, consiste em transmitir o máximo de informações com o mínimo de palavras, sem eliminar passagens essenciais ao entendimento do texto.',
      'Correto. Segundo o MRPR, a CONCISÃO consiste em transmitir o MÁXIMO de informações com o MÍNIMO de palavras.\nMas atenção: concisão NÃO é economia a qualquer custo. Não se pode:\n• eliminar informações essenciais;\n• sacrificar a clareza;\n• tornar o texto telegráfico ou obscuro.\nO que se elimina são redundâncias, repetições, adjetivação excessiva e frases-feitas ("venho por meio deste", "sem mais para o momento").\nConcisão + clareza = texto eficiente.'),
    q(T71, M7, 'E', 'A redação oficial deve empregar jargões técnicos e termos estrangeiros sem explicação, uma vez que seus destinatários são sempre especialistas na matéria.',
      'Errado. Pelo atributo da CLAREZA, a redação oficial deve EVITAR:\n• jargões técnicos ou burocráticos desnecessários;\n• estrangeirismos, quando houver equivalente em português;\n• siglas não explicadas (na primeira ocorrência, deve-se escrever por extenso).\nQuando um termo técnico for indispensável, ele deve ser EXPLICADO.\nMotivo: as comunicações oficiais podem ser lidas por QUALQUER cidadão, não apenas por especialistas. O texto deve ser acessível a todos, princípio ligado à publicidade e à transparência.'),
    q(T71, M7, 'C', 'Em um expediente oficial, o trecho “Informamos que, conforme já informado anteriormente, as informações solicitadas serão enviadas” contraria a concisão, em razão de redundâncias.',
      'Correto. O trecho é um exemplo de texto PROLIXO, que fere a CONCISÃO.\nProblemas:\n1) Repetição da mesma família de palavras: "Informamos", "informado", "informações".\n2) Pleonasmo vicioso: "já ... anteriormente" (se foi "já informado", é óbvio que foi antes).\n3) A expressão "conforme já informado" pode até ser desnecessária, dependendo do contexto.\nReescrita concisa possível: "Conforme comunicado, os dados solicitados serão enviados."\nDica: a banca costuma usar redundâncias (subir para cima, elo de ligação, há anos atrás, já... anteriormente) para testar a concisão.'),
    q(T71, M7, 'E', 'A formalidade exigida na redação oficial pressupõe linguagem rebuscada, com o emprego de arcaísmos e de construções preciosistas.',
      'Errado. FORMALIDADE não se confunde com REBUSCAMENTO.\nO MRPR recomenda linguagem formal, ou seja, norma-padrão, tratamento adequado e civilidade. Mas ela deve ser SIMPLES e CLARA.\nDevem ser evitados:\n• arcaísmos (palavras em desuso: "outrossim", "destarte", em excesso);\n• preciosismos (palavras difíceis só para "enfeitar");\n• construções sintáticas complexas e frases longas;\n• chavões burocráticos.\nO objetivo da comunicação oficial é ser COMPREENDIDA, e não impressionar o leitor.'),
    q(T71, M7, 'C', 'A padronização dos documentos oficiais, inclusive quanto à diagramação, facilita a leitura, a identificação e o tratamento das comunicações.',
      'Correto. A PADRONIZAÇÃO é um dos atributos da redação oficial (o MRPR fala em "formalidade e padronização").\nEla envolve uniformidade de:\n• diagramação (fonte, margens, espaçamento);\n• estrutura (partes do documento: cabeçalho, identificação, data, endereçamento, assunto, texto, fecho, assinatura);\n• tratamento (pronomes e vocativos);\n• nomenclatura dos documentos.\nVantagens: facilita a leitura, a identificação rápida do documento, a tramitação, o tratamento e o arquivamento. Também transmite uma imagem uniforme e profissional da Administração.'),
    q(T71, M7, 'E', 'Segundo o Manual de Redação da Presidência da República, o uso da norma-padrão é dispensável nas comunicações oficiais trocadas internamente entre setores de um mesmo órgão.',
      'Errado. O uso da NORMA-PADRÃO é exigência de TODAS as comunicações oficiais, sem exceção.\nVale para:\n• comunicações externas (para outros órgãos ou para cidadãos);\n• comunicações internas (entre setores do mesmo órgão);\n• e-mails oficiais.\nO fato de a comunicação ser interna não autoriza informalidade ou desvios gramaticais. O servidor se comunica em nome da instituição em qualquer caso.'),
    q(T71, M7, 'C', 'Em um expediente oficial, o trecho “O chefe comunicou ao servidor que seu pedido havia sido aprovado” compromete a clareza, pois o possessivo “seu” pode referir-se tanto ao chefe quanto ao servidor.',
      'Correto. O trecho tem uma AMBIGUIDADE causada pelo pronome possessivo "seu", que fere a CLAREZA.\n"O chefe comunicou ao servidor que SEU pedido havia sido aprovado."\nDe quem é o pedido? Pode ser:\n• do chefe (o chefe tinha feito um pedido e comunica o resultado ao servidor);\n• do servidor (o pedido do servidor foi aprovado).\nReescritas que eliminam a ambiguidade:\n• "...que o pedido DO SERVIDOR havia sido aprovado";\n• "...que o pedido DELE (do servidor) havia sido aprovado".\nDica: o possessivo de 3ª pessoa ("seu/sua") é uma das principais fontes de ambiguidade em prova. Fique atento.'),
    q(T71, M7, 'E', 'A redação oficial dispensa coesão e coerência, desde que o documento observe a padronização formal prevista no Manual.',
      'Errado. COESÃO e COERÊNCIA são atributos expressos da redação oficial no MRPR.\n• Coesão: ligação adequada entre as partes do texto (conectores, retomadas, referências).\n• Coerência: lógica interna do texto, com ideias não contraditórias e progressão adequada.\nA padronização formal (diagramação, estrutura) diz respeito à FORMA do documento. Ela não substitui a necessidade de um CONTEÚDO bem articulado e logicamente organizado.\nUm ofício perfeitamente diagramado, mas incoerente, não cumpre sua função comunicativa.'),

    /* ===== 7.2 Finalidade dos expedientes oficiais ===== */
    q(T72, M7, 'C', 'Com a 3ª edição do Manual de Redação da Presidência da República (2018), aviso e memorando deixaram de existir como tipos distintos, passando a ser tratados sob a denominação única de ofício.',
      'Correto. A 3ª edição do MRPR (2018) trouxe uma importante mudança: UNIFORMIZOU os expedientes.\nAntes, havia três documentos com finalidades distintas:\n• Ofício: para outros órgãos e particulares.\n• Aviso: entre Ministros de Estado.\n• Memorando: comunicação interna, entre unidades do mesmo órgão.\nAgora, todos passaram a se chamar OFÍCIO, seguindo um mesmo padrão (o "padrão ofício").\nContinuam existindo como expedientes específicos, por exemplo, a exposição de motivos e a mensagem.\nEsse ponto é muito cobrado porque muitos materiais antigos ainda citam aviso e memorando.'),
    q(T72, M7, 'E', 'Segundo o Manual de Redação da Presidência da República (2018), o memorando permanece como expediente próprio para a comunicação interna entre unidades de um mesmo órgão, com formato distinto do ofício.',
      'Errado. A 3ª edição do MRPR (2018) EXTINGUIU o memorando como tipo autônomo de documento.\nA comunicação interna, entre unidades de um mesmo órgão, também passou a ser feita por OFÍCIO, no chamado padrão ofício.\nO mesmo aconteceu com o AVISO, antes usado entre Ministros de Estado.\nAtenção: o item seria correto segundo a 2ª edição do Manual (2002). Por isso, cuidado com materiais desatualizados!'),
    q(T72, M7, 'C', 'A exposição de motivos é o expediente dirigido ao Presidente da República ou ao Vice-Presidente para informá-lo de determinado assunto, propor alguma medida ou submeter projeto de ato normativo à sua consideração.',
      'Correto. A EXPOSIÇÃO DE MOTIVOS é o expediente dirigido ao PRESIDENTE DA REPÚBLICA (ou ao Vice-Presidente) para:\na) informá-lo de determinado assunto;\nb) propor alguma medida;\nc) submeter projeto de ato normativo à sua consideração.\nEm regra, é assinada por MINISTRO DE ESTADO. Se o assunto envolver mais de um ministério, a exposição de motivos é assinada por todos os ministros envolvidos (exposição de motivos interministerial).\nDireção do documento: de baixo para cima (Ministro → Presidente).'),
    q(T72, M7, 'E', 'A mensagem é o expediente utilizado por servidores para a comunicação rotineira entre setores de um mesmo órgão.',
      'Errado. A MENSAGEM NÃO é usada para comunicação rotineira entre setores (para isso, usa-se o ofício).\nSegundo o MRPR, a mensagem é o instrumento de comunicação oficial entre os CHEFES DOS PODERES PÚBLICOS, especialmente as enviadas pelo Chefe do Poder EXECUTIVO ao Poder LEGISLATIVO.\nFinalidades típicas:\n• encaminhar projetos de lei;\n• comunicar vetos;\n• informar fatos da administração pública;\n• encaminhar mensagem anual ao Congresso na abertura da sessão legislativa;\n• solicitar autorização (por exemplo, para o Presidente se ausentar do país por mais de 15 dias).'),
    q(T72, M7, 'C', 'A mensagem é o instrumento de comunicação oficial entre os Chefes dos Poderes Públicos, destacando-se as enviadas pelo Chefe do Poder Executivo ao Poder Legislativo para informar fatos da administração ou encaminhar projetos de lei, por exemplo.',
      'Correto. Esta é a definição de MENSAGEM segundo o MRPR: instrumento de comunicação oficial entre os CHEFES DOS PODERES PÚBLICOS, notadamente as mensagens enviadas pelo Chefe do Poder EXECUTIVO ao Poder LEGISLATIVO.\nFinalidades:\n• encaminhar projetos de lei ordinária, complementar ou financeira;\n• comunicar vetos (total ou parcial) a projetos de lei;\n• encaminhar medidas provisórias;\n• informar fatos da administração pública;\n• indicar autoridades para cargos que dependem de aprovação do Senado.\nResumo dos expedientes: Mensagem = Presidente → Congresso; Exposição de motivos = Ministro → Presidente; Ofício = demais comunicações.'),
    q(T72, M7, 'E', 'A exposição de motivos é dirigida pelo Presidente da República aos Ministros de Estado para orientá-los quanto à execução de políticas públicas.',
      'Errado. O item inverte a direção da exposição de motivos.\n• Correto: a exposição de motivos é dirigida AO Presidente da República (ou ao Vice-Presidente), em regra POR um Ministro de Estado.\n• O item: diz que vai DO Presidente PARA os Ministros, o que está errado.\nFinalidades: informar o Presidente sobre assunto, propor medida ou submeter projeto de ato normativo à sua consideração.\nMacete: a exposição de motivos "sobe" (do ministério para a Presidência). Os ministros EXPÕEM os MOTIVOS ao Presidente para que ele decida.'),
    q(T72, M7, 'C', 'O ofício pode ser utilizado para o tratamento de assuntos oficiais tanto entre órgãos da administração pública quanto entre estes e particulares.',
      'Correto. O OFÍCIO é o expediente mais amplo do padrão oficial. Pode ser usado:\n• entre órgãos e entidades da administração pública (inclusive de diferentes esferas e Poderes);\n• entre órgãos da administração e PARTICULARES (cidadãos, empresas);\n• internamente, entre unidades do mesmo órgão (função que antes era do memorando).\nDesde a 3ª edição do MRPR (2018), o ofício absorveu as funções do aviso e do memorando.'),
    q(T72, M7, 'E', 'Por sua natureza informal, o correio eletrônico não pode ser empregado como meio de comunicação oficial.',
      'Errado. O MRPR RECONHECE o CORREIO ELETRÔNICO (e-mail) como forma de comunicação oficial.\nNa verdade, ele se tornou uma das principais formas de comunicação pela agilidade e pelo baixo custo.\nMas ATENÇÃO: o e-mail oficial deve observar a linguagem própria da redação oficial: norma-padrão, formalidade, clareza, impessoalidade, campo "assunto" preenchido de forma precisa e fecho adequado.\nO fato de ser eletrônico não autoriza informalidade.'),
    q(T72, M7, 'C', 'Segundo o Manual de Redação da Presidência da República, para que a mensagem de correio eletrônico tenha valor documental, é necessária certificação digital que ateste a identidade do remetente.',
      'Correto. Segundo o MRPR, para que a mensagem de correio eletrônico tenha VALOR DOCUMENTAL, isto é, para que possa ser aceita como DOCUMENTO ORIGINAL, é necessária CERTIFICAÇÃO DIGITAL que ateste a identidade do remetente, nos termos da legislação.\nPor quê? A certificação digital garante:\n• autenticidade (quem enviou é realmente quem diz ser);\n• integridade (o conteúdo não foi alterado);\n• não repúdio (o remetente não pode negar o envio).\nSem certificação, o e-mail continua sendo comunicação oficial válida, mas não tem valor de documento original.'),
    q(T72, M7, 'E', 'O ofício destina-se exclusivamente à comunicação entre autoridades que ocupam o mesmo nível hierárquico.',
      'Errado. O ofício NÃO se restringe a autoridades de mesmo nível hierárquico.\nEle é usado:\n• entre autoridades de QUAISQUER níveis hierárquicos (superior, igual ou inferior);\n• entre a administração e PARTICULARES.\nO nível hierárquico influencia apenas aspectos formais, como:\n• o FECHO: "Respeitosamente" para superiores; "Atenciosamente" para mesmo nível, inferiores e particulares;\n• o PRONOME DE TRATAMENTO e o VOCATIVO (Vossa Excelência / Vossa Senhoria).\nDica: "exclusivamente" é forte indício de item errado.'),

    /* ===== 7.3 Adequação da linguagem ao documento ===== */
    q(T73, M7, 'C', 'Em ofício dirigido a Ministro de Estado, o pronome de tratamento adequado é “Vossa Excelência”, e o vocativo adequado é “Senhor Ministro,”.',
      'Correto. Pelo MRPR, os Ministros de Estado recebem o tratamento "VOSSA EXCELÊNCIA".\nQuanto ao VOCATIVO, existem duas formas:\n• "EXCELENTÍSSIMO SENHOR + cargo": reservado aos CHEFES DE PODER (Presidente da República, Presidente do Congresso Nacional e Presidente do STF).\n• "SENHOR + cargo": demais autoridades tratadas por Vossa Excelência, como Ministros, Deputados, Senadores, Juízes e Governadores.\nPortanto, para Ministro: "Senhor Ministro," (com vírgula, como todo vocativo).'),
    q(T73, M7, 'E', 'Segundo o Manual de Redação da Presidência da República, o superlativo “Ilustríssimo” continua recomendado no endereçamento de comunicações dirigidas a particulares.',
      'Errado. O MRPR DISPENSA o uso de "ILUSTRÍSSIMO" (e de sua abreviatura "Ilmo.") para as autoridades tratadas por Vossa Senhoria e para os particulares.\nBasta usar "SENHOR" ou "SENHORA": "Senhor Fulano de Tal,".\nO Manual adota a ideia de que superlativos e títulos protocolares excessivos devem ser abandonados, em favor da simplicidade e da objetividade.\nNa mesma linha, também foi abolido o "Digníssimo" (DD).'),
    q(T73, M7, 'C', 'Em ofício dirigido a um homem, o trecho “Vossa Senhoria será informado do resultado” está correto quanto à concordância, com o verbo na terceira pessoa e o adjetivo no masculino.',
      'Correto. Duas regras de concordância com PRONOMES DE TRATAMENTO, muito cobradas:\n1) O VERBO vai para a 3ª PESSOA (embora o pronome seja usado para falar COM a pessoa): "Vossa Senhoria SERÁ informado" (e não "sereis").\n2) ADJETIVOS e PARTICÍPIOS concordam com o SEXO da pessoa, e não com o gênero gramatical da expressão (que é feminino: "Vossa Senhoria"):\n• Para um homem: "Vossa Senhoria será informadO".\n• Para uma mulher: "Vossa Senhoria será informadA".\nOutro exemplo: "Vossa Excelência está cansadO?" (dirigido a um ministro).'),
    q(T73, M7, 'E', 'Os pronomes possessivos referentes a “Vossa Excelência” devem ser da segunda pessoa do plural, como em “Comunico a Vossa Excelência que vosso pedido foi deferido”.',
      'Errado. Apesar da palavra "VOSSA", os pronomes de tratamento levam a concordância para a 3ª PESSOA, inclusive os possessivos.\n• Correto: "Comunico a Vossa Excelência que SEU pedido foi deferido."\n• Errado: "...que VOSSO pedido foi deferido."\nRegra completa: com pronomes de tratamento, usam-se verbos, pronomes possessivos (seu, sua) e pronomes oblíquos (o, a, lhe, se) da 3ª pessoa.\nEx.: "Vossa Senhoria deve trazer SEUS documentos; caso contrário, não O poderemos atender."'),
    q(T73, M7, 'C', 'O Manual de Redação da Presidência da República considera desnecessário o emprego de “Digníssimo” (DD) nas comunicações oficiais, pois a dignidade é pressuposto para o exercício de qualquer cargo público.',
      'Correto. O MRPR ABOLIU o uso de "DIGNÍSSIMO" (DD) nas comunicações oficiais.\nJustificativa do próprio Manual: a dignidade é PRESSUPOSTO para o exercício de qualquer cargo público e, por isso, não precisa ser reafirmada a cada comunicação.\nJunto com o "Ilustríssimo" (também dispensado), isso reflete a tendência de SIMPLIFICAÇÃO da linguagem oficial, eliminando formalidades vazias.'),
    q(T73, M7, 'E', 'Emprega-se “Vossa Excelência” quando se fala a respeito da autoridade, e “Sua Excelência” quando o emissor se dirige diretamente a ela.',
      'Errado. O item inverteu as formas. A regra é:\n• "VOSSA Excelência" → quando se fala COM a autoridade (dirigindo-se diretamente a ela, 2ª pessoa do discurso). Ex.: "Informo a Vossa Excelência que..."\n• "SUA Excelência" → quando se fala SOBRE a autoridade, referindo-se a ela (3ª pessoa do discurso). Ex.: "Sua Excelência, o Ministro, participará do evento."\nMacete: VOSSA → VOcê (falo com você); SUA → ele/ela (falo dele, sobre ele).\nA mesma regra vale para Vossa/Sua Senhoria, Vossa/Sua Santidade, Vossa/Sua Majestade.'),
    q(T73, M7, 'C', 'Em comunicação dirigida ao Presidente da República, o vocativo adequado é “Excelentíssimo Senhor Presidente da República,”.',
      'Correto. O vocativo "EXCELENTÍSSIMO SENHOR + cargo" é reservado aos CHEFES DE PODER:\n• Presidente da República → "Excelentíssimo Senhor Presidente da República,"\n• Presidente do Congresso Nacional → "Excelentíssimo Senhor Presidente do Congresso Nacional,"\n• Presidente do Supremo Tribunal Federal → "Excelentíssimo Senhor Presidente do Supremo Tribunal Federal,"\nAs demais autoridades tratadas por "Vossa Excelência" recebem o vocativo "Senhor + cargo" (ex.: "Senhor Ministro,", "Senhor Senador,").\nLembre-se: o vocativo termina com vírgula.'),
    q(T73, M7, 'E', 'Segundo o Manual de Redação da Presidência da República, “Doutor” é forma de tratamento obrigatória para qualquer autoridade com formação de nível superior.',
      'Errado. Para o MRPR, "DOUTOR" NÃO é forma de tratamento, e sim TÍTULO ACADÊMICO, conferido a quem concluiu doutorado.\nSeu uso indiscriminado deve ser EVITADO, mesmo para autoridades com formação superior (bacharéis em Direito, médicos etc.).\nNas comunicações oficiais, usam-se "SENHOR" ou "SENHORA".\nO Manual admite o emprego de "doutor" apenas para quem tenha efetivamente o título de doutor (pós-graduação).\nDica: "obrigatória" é termo forte que, aqui, indica item errado.'),
    q(T73, M7, 'C', 'Em ofício dirigido a um cidadão, é adequado o tratamento “Vossa Senhoria”, com o vocativo “Senhor” seguido do nome do destinatário.',
      'Correto. "VOSSA SENHORIA" é o pronome de tratamento usado para:\n• as demais autoridades (que não recebem Vossa Excelência);\n• os PARTICULARES (cidadãos em geral).\nVocativo adequado: "SENHOR" ou "SENHORA" + nome: "Senhor Fulano de Tal,".\nLembre-se de que o MRPR dispensa o "Ilustríssimo" nesses casos.\nResumo do tratamento:\n• Chefes de Poder → Vossa Excelência / "Excelentíssimo Senhor + cargo".\n• Demais autoridades de alto escalão → Vossa Excelência / "Senhor + cargo".\n• Demais autoridades e particulares → Vossa Senhoria / "Senhor + nome".'),
    q(T73, M7, 'E', 'Em ofício dirigido a Ministro de Estado, o vocativo adequado é “Excelentíssimo Senhor Ministro,”.',
      'Errado. O vocativo "EXCELENTÍSSIMO SENHOR" é exclusivo dos CHEFES DE PODER (Presidente da República, Presidente do Congresso Nacional e Presidente do STF).\nPara um Ministro de Estado, que recebe o tratamento "Vossa Excelência" mas não é Chefe de Poder, o vocativo correto é:\n"SENHOR MINISTRO,"\nEssa distinção é uma das pegadinhas mais frequentes de redação oficial em concursos.'),

    /* ===== 7.4 Adequação do formato ao gênero ===== */
    q(T74, M7, 'C', 'No padrão ofício, integram a estrutura do documento, entre outras partes, o cabeçalho, a identificação do expediente, o local e a data, o endereçamento, o assunto, o texto, o fecho e a identificação do signatário.',
      'Correto. Segundo a 3ª edição do MRPR, o documento no PADRÃO OFÍCIO tem as seguintes partes:\n1) Cabeçalho (com o brasão e o nome do órgão).\n2) Identificação do expediente (ex.: "OFÍCIO Nº 12/2026/DG/PRF").\n3) Local e data.\n4) Endereçamento (destinatário).\n5) Assunto.\n6) Texto do documento (introdução, desenvolvimento e conclusão).\n7) Fecho ("Respeitosamente" ou "Atenciosamente").\n8) Identificação do signatário (nome e cargo).\n9) Numeração das páginas (a partir da segunda).\nO item cita "entre outras partes", o que torna a enumeração correta.'),
    q(T74, M7, 'E', 'Em comunicação oficial dirigida ao Presidente da República, o fecho adequado é “Atenciosamente,”.',
      'Errado. O MRPR prevê apenas DOIS fechos para as comunicações oficiais:\n• "RESPEITOSAMENTE," → para autoridades de hierarquia SUPERIOR à do remetente, INCLUSIVE o Presidente da República.\n• "ATENCIOSAMENTE," → para autoridades de MESMA hierarquia, de hierarquia INFERIOR e para os demais casos (particulares).\nComo o Presidente da República é a autoridade máxima do Executivo, o fecho adequado é "Respeitosamente,".\nLembre-se: o fecho é seguido de vírgula.'),
    q(T74, M7, 'C', 'Em ofício dirigido por uma autoridade a outra de mesma hierarquia, o fecho adequado é “Atenciosamente,”.',
      'Correto. "ATENCIOSAMENTE," é o fecho usado para:\n• autoridades de MESMA hierarquia;\n• autoridades de hierarquia INFERIOR;\n• particulares e demais casos.\nJá "RESPEITOSAMENTE," é reservado a autoridades de hierarquia SUPERIOR à do remetente, incluindo o Presidente da República.\nMacete: Respeito para cima (superiores); Atenção para os lados e para baixo (iguais, inferiores e particulares).'),
    q(T74, M7, 'E', 'No padrão ofício, as comunicações assinadas pelo Presidente da República devem trazer, abaixo da assinatura, o nome e o cargo do signatário.',
      'Errado. O MRPR prevê uma EXCEÇÃO justamente para o Presidente da República.\nRegra geral: todas as comunicações oficiais devem trazer, abaixo da assinatura, a identificação do signatário (NOME e CARGO).\nExceção: as comunicações assinadas pelo PRESIDENTE DA REPÚBLICA não trazem nome e cargo abaixo da assinatura.\nMotivo: a autoridade e o cargo do Presidente são de conhecimento geral; sua identificação é dispensável.'),
    q(T74, M7, 'C', 'Na identificação do signatário, nas comunicações oficiais em geral, constam o nome e o cargo da autoridade que expede o documento, abaixo do espaço destinado à assinatura.',
      'Correto. Nas comunicações oficiais em geral, a IDENTIFICAÇÃO DO SIGNATÁRIO segue este padrão:\n(espaço para assinatura)\nNOME DA AUTORIDADE\nCargo\nA única exceção são as comunicações assinadas pelo PRESIDENTE DA REPÚBLICA, que dispensam essa identificação.\nFinalidade: permitir que o destinatário saiba exatamente quem é o responsável pelo documento, o que se liga à transparência e à responsabilização.'),
    q(T74, M7, 'E', 'O Manual de Redação da Presidência da República (2018) recomenda, para o texto do ofício, a fonte Times New Roman em corpo 14.',
      'Errado. Segundo a 3ª edição do MRPR (2018), a fonte padrão é CALIBRI ou CARLITO (esta última é a alternativa livre, de código aberto), nos seguintes tamanhos:\n• corpo 12 → texto em geral;\n• corpo 11 → citações recuadas;\n• corpo 10 → notas de rodapé.\n"Times New Roman" era a fonte prevista na edição anterior do Manual (2002), em corpo 12. O item mistura informações desatualizadas e tamanho incorreto.\nFique atento às mudanças da 3ª edição: fonte, extinção do aviso e do memorando, e padrão ofício único.'),
    q(T74, M7, 'C', 'No padrão ofício, local e data são informados por extenso quanto ao mês, como em “Brasília, 15 de março de 2026.”, com alinhamento à direita.',
      'Correto. No padrão ofício, LOCAL e DATA seguem estas regras:\n• Nome da cidade, seguido de vírgula.\n• Dia em algarismos arábicos, sem zero à esquerda.\n• Mês POR EXTENSO e com inicial minúscula.\n• Ano sem ponto de milhar.\n• Ponto-final ao término.\n• ALINHAMENTO À DIREITA.\nExemplo: "Brasília, 15 de março de 2026."\nErros comuns: "Brasília, 15/03/2026" (mês em número), "Brasília, 15 de Março de 2026" (maiúscula), "2.026" (ponto no ano).'),
    q(T74, M7, 'E', 'No padrão ofício, o campo “Assunto” deve reproduzir integralmente o primeiro parágrafo do texto, a fim de evitar ambiguidades.',
      'Errado. O campo "ASSUNTO" deve RESUMIR o teor do documento de forma BREVE e precisa.\nFinalidade: permitir que o destinatário identifique rapidamente a matéria tratada, o que facilita a triagem, a tramitação e o arquivamento.\nReproduzir integralmente o primeiro parágrafo:\n• ferirá a CONCISÃO;\n• tornará o campo extenso e inútil para identificação rápida.\nExemplo adequado: "Assunto: Solicitação de reforço de efetivo para a Operação Carnaval."\nNo padrão ofício, o assunto vem em negrito, precedido de "Assunto:".'),
    q(T74, M7, 'C', 'Na identificação do expediente no padrão ofício, constam o nome do documento, o número, o ano e a sigla do órgão que o expede, como em “OFÍCIO Nº 12/2026/DG/PRF”.',
      'Correto. A IDENTIFICAÇÃO DO EXPEDIENTE, no padrão ofício, reúne:\n1) Nome do documento (em maiúsculas): OFÍCIO.\n2) Indicação de número: "Nº" + número de ordem.\n3) Ano.\n4) Sigla da unidade/setor e do órgão expedidor, da menor para a maior hierarquia, separadas por barra.\nExemplo: "OFÍCIO Nº 12/2026/DG/PRF" (Ofício número 12, de 2026, da Diretoria-Geral da Polícia Rodoviária Federal).\nA identificação fica alinhada à margem esquerda, logo abaixo do cabeçalho.'),
    q(T74, M7, 'E', 'No padrão ofício, a margem lateral esquerda deve ter 1,5 cm, e a margem lateral direita, no mínimo 3 cm.',
      'Errado. O item inverteu as medidas. Segundo o MRPR (3ª ed.), as margens do padrão ofício são:\n• Lateral ESQUERDA: no mínimo 3 cm.\n• Lateral DIREITA: 1,5 cm.\n• Superior e inferior: 2 cm.\nMotivo prático da margem esquerda maior: facilitar a encadernação e o arquivamento em pastas, sem que o furador ou a grampeação atinja o texto.\nMacete: a margem maior fica do lado em que se prende o papel (o esquerdo).')
  ]);
})();
